-- One installation, one current membership. Run as migration owner, not a client.
create schema if not exists private;
revoke all on schema private from public;
create table public.users(id uuid primary key references auth.users(id), email text not null);
create table public.memberships(user_id uuid primary key references public.users(id), role text not null check(role in ('user','spec-user','admin')), active boolean not null default true);
create table public.sites(id uuid primary key, domain text unique not null check(domain=lower(domain)), owner_id uuid not null references public.users(id), input jsonb not null, revision integer not null default 0 check(revision>=0), draft_id uuid, published_id uuid, generation_status text not null default 'queued', domain_status text not null default 'unconfigured');
create table public.assignments(site_id uuid references public.sites(id), user_id uuid references public.users(id), primary key(site_id,user_id));
create table private.batches(id uuid primary key, owner_id uuid not null references public.users(id), created_at timestamptz not null default clock_timestamp());
create table private.workers(id uuid primary key, name text not null, token_hash text unique not null check(length(token_hash)=64), revoked_at timestamptz, created_at timestamptz not null default clock_timestamp());
create table private.jobs(id uuid primary key, site_id uuid not null references public.sites(id), data jsonb not null, worker_id uuid references private.workers(id), generation bigint not null default 0, expires_at timestamptz, checkpoint_id uuid, unique(id,site_id));
create index jobs_site on private.jobs(site_id);
create table private.site_operations(site_id uuid primary key references public.sites(id), operation_id uuid not null, kind text not null check(kind in ('controller','job','publication')), generation bigint, expires_at timestamptz);
create table private.artifacts(id uuid primary key, site_id uuid not null references public.sites(id), manifest jsonb not null, verified boolean not null default false, unique(id,site_id));
create table public.revisions(id uuid primary key, site_id uuid not null references public.sites(id), parent_id uuid, manifest_id uuid not null, kind text not null check(kind in ('draft','candidate','published')), created_at bigint not null, unique(id,site_id), foreign key(manifest_id,site_id) references private.artifacts(id,site_id), foreign key(parent_id,site_id) references public.revisions(id,site_id));
alter table public.sites add foreign key(draft_id,id) references public.revisions(id,site_id), add foreign key(published_id,id) references public.revisions(id,site_id);
create table private.edit_requests(id uuid primary key, site_id uuid not null references public.sites(id), job_id uuid not null references private.jobs(id) deferrable initially deferred, data jsonb not null);
create table public.chat(id uuid primary key, site_id uuid not null references public.sites(id), candidate_id uuid not null, role text not null check(role in ('user','assistant')), text text not null, created_at bigint not null);
create table private.deployments(id uuid primary key, site_id uuid not null references public.sites(id), data jsonb not null);
create table public.health(site_id uuid primary key references public.sites(id), status text not null, checked_at bigint);
create table private.audit(id bigint generated always as identity primary key, actor_id uuid, action text not null, target_id uuid, created_at timestamptz not null default clock_timestamp());
create table private.upload_preparations(id uuid primary key, site_id uuid not null references public.sites(id), job_id uuid not null, worker_id uuid not null references private.workers(id), generation bigint not null, purpose text not null check(purpose in ('artifact','checkpoint')), expected_checkpoint_id uuid, metadata jsonb not null, expires_at timestamptz not null, completed_at timestamptz, foreign key(job_id,site_id) references private.jobs(id,site_id));
create table private.checkpoints(id uuid primary key, site_id uuid not null references public.sites(id), job_id uuid not null, worker_id uuid not null references private.workers(id), generation bigint not null, expected_checkpoint_id uuid, metadata jsonb not null, manifest_id uuid, unique(id,job_id), foreign key(job_id,site_id) references private.jobs(id,site_id), foreign key(manifest_id,site_id) references private.artifacts(id,site_id), foreign key(expected_checkpoint_id,job_id) references private.checkpoints(id,job_id));
alter table private.jobs add foreign key(checkpoint_id,id) references private.checkpoints(id,job_id);
alter table private.upload_preparations add foreign key(expected_checkpoint_id,job_id) references private.checkpoints(id,job_id);
create table private.catalog(kind text not null check(kind in ('style','reference')), id text not null, data jsonb not null, primary key(kind,id));
create table private.invitations(id uuid primary key, email text not null, role text not null check(role in ('user','spec-user','admin')), user_id uuid references public.users(id), state text not null check(state in ('pending','completed')), unique(email));
create function private.immutable_record() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'immutable record'; end $$;
create trigger immutable_revision before update or delete on public.revisions for each row execute function private.immutable_record();
create trigger immutable_artifact before update or delete on private.artifacts for each row execute function private.immutable_record();
create trigger immutable_checkpoint before update or delete on private.checkpoints for each row execute function private.immutable_record();
create function private.current_role() returns text language sql stable security definer set search_path='' as $$ select role from public.memberships where user_id=auth.uid() and active $$;
create function private.can_read_site(target uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.current_role() is not null and exists(select 1 from public.sites s where s.id=target and (private.current_role()='admin' or s.owner_id=auth.uid() or exists(select 1 from public.assignments a where a.site_id=s.id and a.user_id=auth.uid()))) $$;
revoke all on function private.current_role(),private.can_read_site(uuid),private.immutable_record() from public;
grant usage on schema private to authenticated;
grant execute on function private.current_role(),private.can_read_site(uuid) to authenticated;
alter table public.users enable row level security;
alter table public.memberships enable row level security;
alter table public.sites enable row level security;
alter table public.assignments enable row level security;
alter table public.revisions enable row level security;
alter table public.chat enable row level security;
alter table public.health enable row level security;
create policy users_read on public.users for select to authenticated using(private.current_role()='admin' or (id=auth.uid() and private.current_role() is not null));
create policy membership_read on public.memberships for select to authenticated using(private.current_role()='admin' or (user_id=auth.uid() and active));
create policy sites_read on public.sites for select to authenticated using(private.can_read_site(id));
create policy assignments_read on public.assignments for select to authenticated using(private.can_read_site(site_id));
create policy revisions_read on public.revisions for select to authenticated using(private.can_read_site(site_id));
create policy chat_read on public.chat for select to authenticated using(private.can_read_site(site_id));
create policy health_read on public.health for select to authenticated using(private.can_read_site(site_id));
-- No client write grants/policies: owner, role, assignment and revision mutations are API-only.
revoke all on all tables in schema public from anon,authenticated;
revoke all on all tables in schema private from public,anon,authenticated;
grant select on public.users,public.memberships,public.sites,public.assignments,public.chat,public.health to authenticated;
grant select(id,site_id,parent_id,kind,created_at) on public.revisions to authenticated;
revoke all on all functions in schema private from public,anon;
